#!/usr/bin/env sh
# fetch AGIT (Agência para a Gestão do Sistema Intermodal da Região de Coimbra)  (PT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://dados.gov.pt/s/resources/metro-mondego/20260817-153951-d08309cb/20251219-export-gtfs.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
